      "activity_name": "Execute performance tests",
      "activity_description": "Run performance tests for both Kafka versions across all payload/sink combinations, collect metrics, and ensure repeatability.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A1.4",
      "activity_name": "Analyze and document performance differences",
      "activity_description": "Compare results between 0.8.1 and 0.8.2, summarize findings, and produce a report for stakeholders.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2.1",
