      "activity_name": "Modify RPM scripts for multiple instances",
      "activity_description": "Update RPM packaging to support multiple instances: separate config directories, PID files, log directories, and init script parameters.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A6.3",
      "activity_name": "Test multiple container instances",
      "activity_description": "Install the RPM on a test VM, start multiple xd-container instances, and verify they run independently without conflicts.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A6.4",
      "activity_name": "Update deployment documentation",
      "activity_description": "Document the new multi-instance capability in the RPM deployment guide.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A7.1",
      "activity_name": "Review existing OOTB batch jobs documentation",
      "activity_description": "Examine current documentation for out-of-the-box batch jobs to understand structure and gaps.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A7.2",
      "activity_name": "Improve documentation navigation for batch jobs",
