      "most_likely_effort": 8
    },
    {
      "activity_id": "A7.3",
      "activity_name": "Add cross-references and index for batch jobs",
      "activity_description": "Insert links from overview pages to detailed job descriptions and create an index of all OOTB batch jobs.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A7.4",
      "activity_name": "Validate documentation changes",
      "activity_description": "Review changes with stakeholders or peers to ensure clarity and completeness.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A8.1",
      "activity_name": "Review analytics tab documentation",
      "activity_description": "Assess current analytics tab documentation to identify missing explanations for streaming pipeline widgets.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A8.2",
      "activity_name": "Enhance analytics tab documentation",
